class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        curr_max = 0
        added = 0
        idx = 0
        n = len(coins)
        while curr_max < target:
            if idx < n and coins[idx] <= curr_max + 1:
                curr_max += coins[idx]
                idx += 1
            else:
                curr_max += curr_max + 1
                added += 1
        return added

class Solution {
public:
    int minimumAddedCoins(vector<int>& coins, int target) {
        sort(coins.begin(), coins.end());
        long long curr_max = 0;
        int added = 0, idx = 0, n = coins.size();
        while (curr_max < target) {
            if (idx < n && coins[idx] <= curr_max + 1) {
                curr_max += coins[idx++];
            } else {
                curr_max += curr_max + 1;
                added++;
            }
        }
        return added;
    }
};

class Solution {
    public int minimumAddedCoins(int[] coins, int target) {
        Arrays.sort(coins);
        long currMax = 0;
        int added = 0, idx = 0, n = coins.length;
        while (currMax < target) {
            if (idx < n && coins[idx] <= currMax + 1) {
                currMax += coins[idx++];
            } else {
                currMax += currMax + 1;
                added++;
            }
        }
        return added;
    }
}

